-- vyora-oauth — publication de l'artefact (32510 caractères, 7 tranches).
-- Généré par scripts/build-edge-loader.mjs : ne pas éditer.
delete from public._edge_function_artifact_slices where name = 'vyora-oauth';

insert into public._edge_function_artifact_slices(name, part, chunk)
values
  ('vyora-oauth', 0, ''),
  ('vyora-oauth', 1, ''),
  ('vyora-oauth', 2, ''),
  ('vyora-oauth', 3, ''),
  ('vyora-oauth', 4, ''),
  ('vyora-oauth', 5, ''),
  ('vyora-oauth', 6, '');

-- Le chargeur déployé recompose exactement ces tranches : on vérifie ici ce
-- qu'il lira, et non une constante recopiée à la main.
do $artifact$
declare
  assembled text;
  parts integer;
begin
  select count(*), string_agg(chunk, '' order by part)
    into parts, assembled
  from public._edge_function_artifact_slices where name = 'vyora-oauth';

  if assembled is null or parts <> 7 then
    raise exception 'artefact % : % tranches publiées au lieu de %',
      'vyora-oauth', coalesce(parts, 0), 7;
  end if;
  if exists (
    select 1 from public._edge_function_artifact_slices
    where name = 'vyora-oauth'
      and (part < 0 or part >= 7
           or length(chunk) = 0 or length(chunk) > 2000)
  ) then
    raise exception 'artefact % : numérotation ou taille de tranche invalide', 'vyora-oauth';
  end if;
  if length(assembled) <> 13068 then
    raise exception 'artefact % : % caractères base64 au lieu de %',
      'vyora-oauth', length(assembled), 13068;
  end if;
  if md5(assembled) <> 'e4a4d3e7ead7996439f4fe78ac6ec0d5' then
    raise exception 'artefact % : empreinte des tranches différente du chargeur', 'vyora-oauth';
  end if;
  raise notice 'artefact % publié : % caractères, % tranches, sha256 %',
    'vyora-oauth', 32510, 7, '181204c4e57133005532f695c4627379f3664b337736d75a3d39ef8e9102dfe3';
end
$artifact$;
